import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';
import { promisify } from 'util';

const lstat = promisify(fs.lstat);
const readFile = promisify(fs.readFile);
const writeFile = promisify(fs.writeFile);
const mkdir = promisify(fs.mkdir);
const unlink = promisify(fs.unlink);
const realpath = promisify(fs.realpath);

interface TenantConfig {
  tenantId: string;
  baseDir: string;
  maxFileSize: number;
  allowedFormats: string[];
}

interface ProcessingJob {
  inputPath: string;
  outputPath: string;
  operation: 'resize' | 'crop' | 'watermark';
  tenantId: string;
}

class TenantIsolationGuard {
  private tenantRoots: Map<string, string> = new Map();

  registerTenant(config: TenantConfig): void {
    const resolvedBase = path.resolve(config.baseDir);
    this.tenantRoots.set(config.tenantId, resolvedBase);
  }

  getTenantRoot(tenantId: string): string | undefined {
    return this.tenantRoots.get(tenantId);
  }

  async validatePathOwnership(filePath: string, tenantId: string): Promise<boolean> {
    const tenantRoot = this.tenantRoots.get(tenantId);
    if (!tenantRoot) return false;

    const normalizedPath = path.resolve(filePath);
    if (!normalizedPath.startsWith(tenantRoot + path.sep) && normalizedPath !== tenantRoot) {
      return false;
    }
    return true;
  }
}

class ImageProcessingPipeline {
  private guard: TenantIsolationGuard;
  private processingDir: string;

  constructor(guard: TenantIsolationGuard, processingDir: string) {
    this.guard = guard;
    this.processingDir = path.resolve(processingDir);
  }

  private generateTempPath(tenantId: string, originalName: string): string {
    const hash = crypto.createHash('sha256')
      .update(`${tenantId}-${originalName}-${Date.now()}`)
      .digest('hex').slice(0, 16);
    return path.join(this.processingDir, tenantId, `tmp_${hash}`);
  }

  private async ensureDirectoryExists(dirPath: string): Promise<void> {
    await mkdir(dirPath, { recursive: true });
  }

  private async verifyNotSymlink(filePath: string): Promise<boolean> {
    try {
      const stats = await lstat(filePath);
      return !stats.isSymbolicLink();
    } catch (e: any) {
      if (e.code === 'ENOENT') return true;
      throw e;
    }
  }

  private async safeReadInput(inputPath: string, tenantId: string): Promise<Buffer> {
    const isOwned = await this.guard.validatePathOwnership(inputPath, tenantId);
    if (!isOwned) {
      throw new Error(`Access denied: ${inputPath} not owned by tenant ${tenantId}`);
    }

    const isNotSymlink = await this.verifyNotSymlink(inputPath);
    if (!isNotSymlink) {
      throw new Error(`Security violation: symlink detected at ${inputPath}`);
    }

    // Read the file after symlink check
    const data = await readFile(inputPath);
    return data;
  }

  private async writeOutput(outputPath: string, data: Buffer, tenantId: string): Promise<void> {
    const isOwned = await this.guard.validatePathOwnership(outputPath, tenantId);
    if (!isOwned) {
      throw new Error(`Access denied: ${outputPath} not owned by tenant ${tenantId}`);
    }

    const parentDir = path.dirname(outputPath);
    await this.ensureDirectoryExists(parentDir);

    // Verify the parent directory hasn't been replaced with a symlink
    const parentNotSymlink = await this.verifyNotSymlink(parentDir);
    if (!parentNotSymlink) {
      throw new Error(`Security violation: symlink detected at parent ${parentDir}`);
    }

    // Write to temp location first, then move
    const tempPath = this.generateTempPath(tenantId, path.basename(outputPath));
    const tempDir = path.dirname(tempPath);
    await this.ensureDirectoryExists(tempDir);

    await writeFile(tempPath, data);

    // Final validation before rename - resolve the output path
    const resolvedOutput = path.resolve(outputPath);
    const tenantRoot = this.guard.getTenantRoot(tenantId);
    if (!resolvedOutput.startsWith(tenantRoot! + path.sep)) {
      await unlink(tempPath);
      throw new Error('Path traversal detected during final write');
    }

    fs.renameSync(tempPath, outputPath);
  }

  private applyImageTransform(data: Buffer, operation: string): Buffer {
    // Simulated image processing - in production would use sharp/jimp
    const header = Buffer.from(`PROCESSED_${operation.toUpperCase()}_`);
    return Buffer.concat([header, data]);
  }

  async processJob(job: ProcessingJob): Promise<{ success: boolean; outputSize: number }> {
    const inputData = await this.safeReadInput(job.inputPath, job.tenantId);

    if (inputData.length > 50 * 1024 * 1024) {
      throw new Error('File exceeds maximum size limit');
    }

    const processedData = this.applyImageTransform(inputData, job.operation);
    await this.writeOutput(job.outputPath, processedData, job.tenantId);

    return { success: true, outputSize: processedData.length };
  }
}

// Multi-tenant server setup
async function initializePipeline(): Promise<ImageProcessingPipeline> {
  const guard = new TenantIsolationGuard();

  guard.registerTenant({
    tenantId: 'tenant-alpha',
    baseDir: '/data/tenants/alpha',
    maxFileSize: 10 * 1024 * 1024,
    allowedFormats: ['png', 'jpg', 'webp']
  });

  guard.registerTenant({
    tenantId: 'tenant-beta',
    baseDir: '/data/tenants/beta',
    maxFileSize: 25 * 1024 * 1024,
    allowedFormats: ['png', 'jpg']
  });

  const pipeline = new ImageProcessingPipeline(guard, '/data/processing');
  return pipeline;
}

export { ImageProcessingPipeline, TenantIsolationGuard, initializePipeline };
